func countComponents(_ n: Int, _ edges: [[Int]]) -> Int {
    var adj: [Int: [Int]] = [:]
    for e in edges {
        adj[e[0], default: []].append(e[1])
        adj[e[1], default: []].append(e[0])
    }
    var visited = Set<Int>()
    var count = 0
    for i in 0..<n {
        if !visited.contains(i) {
            count += 1
            var q = [i]
            visited.insert(i)
            while !q.isEmpty {
                let curr = q.removeFirst()
                for neighbor in adj[curr, default: []] {
                    if !visited.contains(neighbor) {
                        visited.insert(neighbor)
                        q.append(neighbor)
                    }
                }
            }
        }
    }
    return count
}
let edges = [[0, 1], [1, 2], [3, 4]]
print(countComponents(5, edges))

func hasPath(_ edges: [[Int]], _ start: Int, _ target: Int) -> Bool {
    var adj: [Int: [Int]] = [:]
    for e in edges {
        adj[e[0], default: []].append(e[1])
    }
    var visited = Set<Int>()
    func dfs(_ curr: Int) -> Bool {
        if curr == target { return true }
        visited.insert(curr)
        for next in adj[curr, default: []] {
            if !visited.contains(next) && dfs(next) { return true }
        }
        return false
    }
    return dfs(start)
}
let edges = [[0, 1], [1, 2], [2, 3], [1, 4]]
print(hasPath(edges, 0, 3), hasPath(edges, 4, 3))

func shortestDistance(_ edges: [[Int]], _ start: Int, _ end: Int) -> Int {
    var adj: [Int: [Int]] = [:]
    for e in edges {
        adj[e[0], default: []].append(e[1])
        adj[e[1], default: []].append(e[0])
    }
    var queue = [start]
    var visited: Set<Int> = [start]
    var dist = 0
    while !queue.isEmpty {
        let count = queue.count
        for _ in 0..<count {
            let u = queue.removeFirst()
            if u == end { return dist }
            for v in adj[u, default: []] {
                if !visited.contains(v) {
                    visited.insert(v)
                    queue.append(v)
                }
            }
        }
        dist += 1
    }
    return -1
}
let edges = [[0, 1], [0, 2], [1, 3], [2, 3], [3, 4]]
print(shortestDistance(edges, 0, 4))

func hasCycle(_ numNodes: Int, _ edges: [[Int]]) -> Bool {
    var adj: [Int: [Int]] = [:]
    for e in edges { adj[e[0], default: []].append(e[1]) }
    var state = Array(repeating: 0, count: numNodes)
    func dfs(_ u: Int) -> Bool {
        if state[u] == 1 { return true }
        if state[u] == 2 { return false }
        state[u] = 1
        for v in adj[u, default: []] {
            if dfs(v) { return true }
        }
        state[u] = 2
        return false
    }
    for i in 0..<numNodes {
        if state[i] == 0 && dfs(i) { return true }
    }
    return false
}
let g1 = [[0, 1], [1, 2], [2, 0]]
let g2 = [[0, 1], [1, 2], [0, 2]]
print("\(hasCycle(3, g1)),\(hasCycle(3, g2))")

func findSources(_ n: Int, _ edges: [[Int]]) -> [Int] {
    var inDegree = Array(repeating: 0, count: n)
    for e in edges { inDegree[e[1]] += 1 }
    var sources: [Int] = []
    for i in 0..<n where inDegree[i] == 0 { sources.append(i) }
    return sources
}
let edges = [[0, 2], [1, 2], [2, 3]]
print(findSources(4, edges))

func countEdges(matrix: [[Int]]) -> Int {
    var count = 0
    let n = matrix.count
    for i in 0..<n {
        for j in 0..<n {
            if matrix[i][j] == 1 { count += 1 }
        }
    }
    return count
}
let grid = [
    [0, 1, 1],
    [1, 0, 0],
    [1, 0, 0]
]
print(countEdges(matrix: grid))

func isBipartite(_ n: Int, _ edges: [[Int]]) -> Bool {
    var adj: [Int: [Int]] = [:]
    for e in edges {
        adj[e[0], default: []].append(e[1])
        adj[e[1], default: []].append(e[0])
    }
    var colors = Array(repeating: 0, count: n)
    for i in 0..<n {
        if colors[i] != 0 { continue }
        var q = [i]
        colors[i] = 1
        while !q.isEmpty {
            let u = q.removeFirst()
            for v in adj[u, default: []] {
                if colors[v] == 0 {
                    colors[v] = -colors[u]
                    q.append(v)
                } else if colors[v] == colors[u] {
                    return false
                }
            }
        }
    }
    return true
}
let triangle = [[0, 1], [1, 2], [2, 0]]
print(isBipartite(3, triangle))

func topoOrder(_ n: Int, _ edges: [[Int]]) -> [Int] {
    var adj: [Int: [Int]] = [:]
    var inDegree = Array(repeating: 0, count: n)
    for e in edges {
        adj[e[0], default: []].append(e[1])
        inDegree[e[1]] += 1
    }
    var q: [Int] = []
    for i in 0..<n where inDegree[i] == 0 { q.append(i) }
    var result: [Int] = []
    while !q.isEmpty {
        let u = q.removeFirst()
        result.append(u)
        for v in adj[u, default: []] {
            inDegree[v] -= 1
            if inDegree[v] == 0 { q.append(v) }
        }
    }
    return result
}
let edges = [[2, 0], [2, 1], [0, 3], [1, 3]]
print(topoOrder(4, edges))

