func findCircleNum(_ isConnected: [[Int]]) -> Int {
    let n = isConnected.count
    var visited = Array(repeating: false, count: n)
    var count = 0
    func dfs(_ i: Int) {
        visited[i] = true
        for j in 0..<n {
            if isConnected[i][j] == 1 && !visited[j] {
                dfs(j)
            }
        }
    }
    for i in 0..<n {
        if !visited[i] {
            count += 1
            dfs(i)
        }
    }
    return count
}

let matrix = [
    [1, 1, 0],
    [1, 1, 0],
    [0, 0, 1]
]
print(findCircleNum(matrix))

